const $=s=>document.querySelector(s);const KEY='qingdan.tasks.v1';const day=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};let tasks=[],view='all',status='pending',editing=null,toastTimer;let storageOK=true;
try{const data=JSON.parse(localStorage.getItem(KEY)||'[]');if(!Array.isArray(data)||data.some(t=>!t||typeof t.id!=='string'||typeof t.title!=='string'||typeof t.done!=='boolean'||!['normal','high','low'].includes(t.priority)||typeof t.due!=='string'||typeof t.notes!=='string'||typeof t.created!=='number'))throw Error();tasks=data}catch{storageOK=false;setTimeout(()=>notify('无法读取本地数据；本次修改暂不保存，请检查浏览器存储。'),100)}
function notify(message,undo){clearTimeout(toastTimer);const box=$('#toast');box.replaceChildren(document.createTextNode(message));if(undo){const b=document.createElement('button');b.textContent='撤销';b.onclick=()=>{undo();box.hidden=true};box.append(b)}box.hidden=false;toastTimer=setTimeout(()=>box.hidden=true,6000)}
function save(){if(storageOK){try{localStorage.setItem(KEY,JSON.stringify(tasks))}catch{notify('保存失败：浏览器存储不可用，请勿关闭页面。')}}render()}
function addTask(title,priority='normal',due='',notes=''){title=String(title).trim();if(!title||title.length>160)throw Error('请输入 1–160 个字符的任务名称');const task={id:crypto.randomUUID(),title,priority,due,notes,done:false,created:Date.now()};tasks.unshift(task);save();return task}
const matchView=(t,v)=>v==='all'||v==='today'&&!t.done&&t.due===day()||v==='important'&&!t.done&&t.priority==='high'||v==='completed'&&t.done;
function render(){const today=day(),pending=tasks.filter(t=>!t.done).length,completed=tasks.length-pending,pct=tasks.length?Math.round(completed/tasks.length*100):0;$('#date').textContent=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date());$('#pending-count').textContent=pending;$('#today-count').textContent=tasks.filter(t=>!t.done&&t.due===today).length;$('#progress-label').innerHTML=`${pct}<em>%</em>`;$('#progress-bar').style.width=pct+'%';const names={all:'全部任务',today:'今天',important:'重要任务',completed:'已完成'};$('#title').textContent=$('#breadcrumb').textContent=names[view];$('#subtitle').textContent=pending?`还有 ${pending} 件待办，按自己的节奏慢慢来。`:'留一点空间，给接下来想做的事。';document.querySelectorAll('#nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false');b.querySelector('b').textContent=tasks.filter(t=>matchView(t,b.dataset.view)&&(b.dataset.view!=='all'||!t.done)).length});$('.tabs').hidden=view==='completed';document.querySelectorAll('[data-status]').forEach(b=>{b.classList.toggle('selected',b.dataset.status===status);b.setAttribute('aria-pressed',String(b.dataset.status===status))});const query=$('#search').value.trim().toLocaleLowerCase();let visible=tasks.filter(t=>matchView(t,view)&&(view==='completed'||status==='all'||!t.done)&&(t.title+' '+t.notes).toLocaleLowerCase().includes(query));const sort=$('#sort').value;visible.sort((a,b)=>sort==='priority'?({high:0,normal:1,low:2}[a.priority]-{high:0,normal:1,low:2}[b.priority])||b.created-a.created:sort==='due'?((a.due||'9999').localeCompare(b.due||'9999'))||b.created-a.created:b.created-a.created);$('#visible-count').textContent=`${visible.length} 项`;const list=$('#task-list');list.replaceChildren();if(!visible.length){const empty=document.createElement('div');empty.className='empty';empty.innerHTML=`<span>✓</span><h2>${query?'没有找到匹配的任务':view==='completed'?'完成的每一步，都值得记录':view==='today'?'今天没有到期任务':view==='important'?'暂无重要任务':'清单很轻，心也轻一点'}</h2><p>${query?'试试其他关键词。':'点击「新建任务」，安排下一件想做的事。'}</p>`;list.append(empty)}visible.forEach(t=>{const row=document.createElement('article');row.className='task'+(t.done?' done':'');const check=document.createElement('input');check.type='checkbox';check.checked=t.done;check.setAttribute('aria-label',(t.done?'标为未完成：':'完成：')+t.title);check.onchange=()=>{t.done=check.checked;save();notify(t.done?'又完成一件事，做得好。':'已恢复为待办')};const body=document.createElement('div');body.className='task-body';const title=document.createElement('button');title.className='task-title';title.textContent=t.title;title.onclick=()=>openEditor(t);const meta=document.createElement('div');meta.className='meta';const badge=document.createElement('span');badge.className='badge '+t.priority;badge.textContent={normal:'普通',high:'⚑ 重要',low:'低优先级'}[t.priority];meta.append(badge);if(t.due){const date=document.createElement('span');date.textContent=(t.due<today&&!t.done?'已逾期 · ':t.due===today?'今天 · ':'')+t.due;date.className=t.due<today&&!t.done?'overdue':'';meta.append(date)}if(t.notes){const note=document.createElement('span');note.textContent='有备注';meta.append(note)}body.append(title,meta);const actions=document.createElement('div');actions.className='task-actions';const edit=document.createElement('button');edit.className='icon-button';edit.textContent='✎';edit.setAttribute('aria-label','编辑 '+t.title);edit.onclick=()=>openEditor(t);const remove=document.createElement('button');remove.className='icon-button';remove.textContent='×';remove.setAttribute('aria-label','删除 '+t.title);remove.onclick=()=>{const index=tasks.indexOf(t);tasks=tasks.filter(x=>x.id!==t.id);save();notify('任务已删除',()=>{tasks.splice(Math.min(index,tasks.length),0,t);save()})};actions.append(edit,remove);row.append(check,body,actions);list.append(row)})}
function openEditor(t){editing=t?.id||null;$('#dialog-title').textContent=t?'编辑任务':'新建任务';$('#edit-title').value=t?.title||'';$('#edit-notes').value=t?.notes||'';$('#edit-priority').value=t?.priority||(view==='important'?'high':'normal');$('#edit-due').value=t?.due||(view==='today'?day():'');$('#editor').showModal();$('#edit-title').focus()}
$('#new-task').onclick=()=>openEditor();$('#close-dialog').onclick=$('#cancel-dialog').onclick=()=>$('#editor').close();$('#edit-form').onsubmit=e=>{e.preventDefault();const title=$('#edit-title').value.trim();if(!title){$('#edit-title').setCustomValidity('请输入任务名称');$('#edit-title').reportValidity();return}const values={title,notes:$('#edit-notes').value.trim(),priority:$('#edit-priority').value,due:$('#edit-due').value};if(editing){const t=tasks.find(t=>t.id===editing);if(!t){notify('任务已不存在，请重新添加');$('#editor').close();return}Object.assign(t,values);save()}else addTask(values.title,values.priority,values.due,values.notes);$('#editor').close();notify(editing?'任务已更新':'已添加到清单')};$('#edit-title').oninput=()=>$('#edit-title').setCustomValidity('');$('#quick-form').onsubmit=e=>{e.preventDefault();try{addTask($('#quick-title').value,view==='important'?'high':'normal',view==='today'?day():'');$('#quick-title').value='';if(view==='completed')view='all';render();notify('已添加到清单')}catch(err){notify(err.message)}};$('#nav').onclick=e=>{const b=e.target.closest('[data-view]');if(b){view=b.dataset.view;render()}};document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{status=b.dataset.status;render()});$('#search').oninput=render;$('#sort').onchange=render;document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();$('#search').focus()}});render();setInterval(render,60000);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'add_task',description:'在轻单中新增一个待办任务。',inputSchema:{type:'object',properties:{title:{type:'string',minLength:1,maxLength:160}},required:['title'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.title!=='string'||Object.keys(input).some(k=>k!=='title'))throw Error('无效的任务参数');const task=addTask(input.title);return {id:task.id,title:task.title,done:task.done}}})).catch(()=>{})}catch{}}
